from pathlib import Path
import sys,json,math,subprocess,hashlib
r=Path(sys.argv[1]);b=(r/'reference.ppm').read_bytes();header,reference=b.split(b'\n',3)[:3],b.split(b'\n',3)[3];assert len(reference)==1024*768*3;full=(r/'full/full.rgb').read_bytes();preview=(r/'full/preview.rgb').read_bytes();cancel=(r/'cancel/preview.rgb').read_bytes();assert full==reference and cancel==preview;f=json.loads((r/'full/results.json').read_text());c=json.loads((r/'cancel/results.json').read_text());assert f['first_ratio']==8 and c['first_ratio']==8 and c['final_provided']==f['first_provided'] and c['final_consumed']==f['first_consumed'] and not c['full'];size=(r/'source.jxl').stat().st_size;assert f['first_provided']<size/2
mse=sum((a-b)**2 for a,b in zip(preview,reference))/len(reference);psnr=10*math.log10(255**2/mse);assert psnr>=20
(r/'truncated.jxl').write_bytes((r/'source.jxl').read_bytes()[:10]);(r/'truncated').mkdir();bad=subprocess.run(['build/catalogue-tools/jxl-progressive',str(r/'truncated.jxl'),str(r/'truncated'),'full'],capture_output=True);(r/'truncated/results.json').write_bytes(bad.stdout);(r/'truncated/stderr.log').write_bytes(bad.stderr);assert bad.returncode!=0
(r/'fresh').mkdir();fresh=subprocess.run(['build/catalogue-tools/jxl-progressive',str(r/'source.jxl'),str(r/'fresh'),'full'],capture_output=True);(r/'fresh/results.json').write_bytes(fresh.stdout);assert fresh.returncode==0 and (r/'fresh/full.rgb').read_bytes()==reference
result={'passed':True,'full_rgb_sha256':hashlib.sha256(reference).hexdigest(),'full_matches_independent_djxl':True,'dc_preview_sha256':hashlib.sha256(preview).hexdigest(),'dc_preview_psnr_db':psnr,'first_intended_downsampling':8,'file_bytes':size,'consumed_to_first_preview':f['first_consumed'],'provided_to_first_preview':f['first_provided'],'first_read_fraction':f['first_provided']/size,'read_ahead_bytes':f['first_provided']-f['first_consumed'],'cancel_same_preview_and_boundary':True,'no_reads_after_cancel':True,'truncated_exit':bad.returncode,'fresh_after_cancel_and_bad_source_exact':True,'decoder_file_owners_closed':True,'physical_transfer_saved':'Not claimed; actual file reads stop early in cancel run, no network/browser latency/energy qualification.'};(r/'results.json').write_text(json.dumps(result,indent=2));print(result)
